// Every chart type keeps FEA-CH-39's promise to a reader, by keyboard and by pointer (FEA-CH-75).
// The every-block report is generated by the release CLI; each of its charts is judged by what its own
// model says it offers, so a type added to the report is covered without a change here:
// - Keyboard: Home and the arrow keys step through the observations, the readout shows the words of the
//   observation the model targets, and Escape clears both.
// - Pointer: hovering an observation's mark targets one and shows its readout; leaving clears both.
// - Legend: where entries are shown, toggling one hides a series and toggling it again restores it.
// - Zoom: the types FEA-CH-39 lists zoom along a numeric or calendar x; any other chart ignores the key.
// - No interaction: a type declared in NO_INTERACTION has no observations and shows no readout.
// `types.json` holds one entry per chart: its policy as read, the three results and `ok`.
import { copyFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
import type { BrowserContext } from 'playwright';
import { harness, verificationShard, watchErrors } from './browser-harness.ts';
import { reports, settle } from './report-runtime.ts';
import { judgeChart } from './chart-interaction-checks.ts';
import type { ChartJudgment } from './chart-interaction-checks.ts';
import type { ChartModel } from './report-model.ts';
import { filterCases } from '../tools/rv-gate/lib/cases.mts';

type Case = { model: ChartModel; index: number };
type Shard = { index: number; count: number; cohort: string[]; selected: string[] };

const h = await harness('chart-interaction');
let inputs: Awaited<ReturnType<typeof reports>> | undefined;
let context: BrowserContext | undefined;
let shard: Shard | undefined;
let caseScope: { cohort: string[]; selected: string[] } | undefined;
let modelCount: number | undefined;
const errors: string[] = [];
const results: (ChartJudgment & { caseKey: string })[] = [];
const started = Date.now();

try {
  inputs = await reports(h.dir, { style: 'sleek', only: ['every-block'], extra: {} });
  // The runner budgets independent shards; one context owns each shard's pointer, focus and runtime.
  context = await h.browser.newContext({ viewport: { width: 1440, height: 900 }, reducedMotion: 'reduce' });
  const page = await context.newPage();
  watchErrors(page, errors);
  // A control that never answers is a finding, not a reason to wait the default 30 s.
  page.setDefaultTimeout(5_000);
  await page.goto(`${inputs.base}/every-block/report.html`);
  const models = await settle(page);
  modelCount = models.length;
  if (!modelCount) errors.push('The every-block report has no chart models');
  if (modelCount !== await page.locator('figure[data-rv-chart]').count()) errors.push(`${modelCount} models for a different number of figures`);
  const key = ({ model, index }: Case) => `${index}:${model.figure}:${model.geometry.kind}`;
  const filtered = filterCases(models.map((model, index) => ({ model, index })), { key });
  caseScope = filtered.scope;
  const selection: { cases: Case[]; shard: Shard } = verificationShard(filtered.cases, { key });
  shard = selection.shard;
  for (const item of selection.cases) {
    const entry = await judgeChart(page, item.index, item.model);
    results.push({ ...entry, caseKey: key(item) });
    if (process.env.RV_TRACE) console.error(item.index, entry.type, entry.ok, Date.now() - started);
  }
  if (JSON.stringify(results.map(entry => entry.caseKey)) !== JSON.stringify(shard.selected)) errors.push('The judged charts do not match the selected shard cases');
} finally {
  const seconds = (Date.now() - started) / 1000;
  const failed = results.filter(entry => !entry.ok);
  try {
    const name = shard && shard.count > 1 ? `types-${shard.index}-of-${shard.count}.json` : 'types.json';
    const saved = h.save(name, { browser: h.browser.version(), style: 'sleek', width: 1440, seconds, charts: results.length, types: new Set(results.map(entry => entry.type)).size, model_count: modelCount, shard, ...(caseScope && { case_scope: caseScope }), completed: results.map(entry => entry.caseKey), failed: failed.length, errors, results });
    // Only the parent writes canonical types.json after proving every shard is complete and disjoint.
    const outAt = process.argv.indexOf('--out');
    if (outAt >= 0 && process.argv[outAt + 1]) { mkdirSync(process.argv[outAt + 1], { recursive: true }); copyFileSync(saved, join(process.argv[outAt + 1], name)); }
  } finally {
    try { await context?.close(); }
    finally { try { await inputs?.close(); } finally { await h.close(); } }
  }
  for (const entry of failed) {
    const why = entry.error ? [`error: ${entry.error}`] : (['keyboard', 'pointer', 'toggle', 'zoom', 'turn'] as const).flatMap(key => (entry[key]?.problems ?? []).map(problem => `${key}: ${problem}`));
    console.error(`FAIL ${entry.type} (chart ${entry.index}, "${entry.title}"): ${why.join('; ')}`);
  }
  if (errors.length) console.error(`browser errors: ${errors.join(' | ')}`);
  if (failed.length || errors.length) process.exitCode = 1;
  else console.log(`PASS ${results.length} charts of ${new Set(results.map(entry => entry.type)).size} types by keyboard and pointer, with legend and zoom where offered, in ${seconds.toFixed(0)} s`);
}
